import os
import abc
import httpx
import json
from typing import Dict, Any, Literal, List, Optional, Union

from agent_org.models import Tool, ToolCall # Import the new Tool and ToolCall models

# Core Abstraction
class LLMProvider(abc.ABC):
    @abc.abstractmethod
    async def generate(self, prompt: str, tools: Optional[List[Tool]] = None) -> Union[str, ToolCall]:
        """
        Generate a text response or a tool call from a prompt.
        Args:
            prompt: The user's prompt.
            tools: An optional list of available tools for the LLM to use.
        Returns:
            A string response, or a ToolCall object if the LLM decides to use a tool.
        """
        pass

# Concrete Implementations
class OpenAIProvider(LLMProvider):
    def __init__(self, model: str = "gpt-4o", api_key: str = None):
        self.model = model
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("OPENAI_API_KEY environment variable not set.")
        self.api_url = "https://api.openai.com/v1/chat/completions"

    async def generate(self, prompt: str, tools: Optional[List[Tool]] = None) -> Union[str, ToolCall]:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }
        messages = [{"role": "user", "content": prompt}]
        json_data: Dict[str, Any] = {
            "model": self.model,
            "messages": messages,
            "temperature": 0.1,
        }

        if tools:
            # Format tools for OpenAI's function calling API
            openai_tools = []
            for tool in tools:
                # Convert Pydantic models to dicts for JSON serialization
                openai_tools.append({
                    "type": "function",
                    "function": tool.model_dump(mode='json') # Use model_dump for Pydantic v2
                })
            json_data["tools"] = openai_tools
            json_data["tool_choice"] = "auto" # Let the model decide whether to call a tool

        async with httpx.AsyncClient() as client:
            resp = await client.post(self.api_url, headers=headers, json=json_data, timeout=60)
            resp.raise_for_status()
            response_data = resp.json()

            choice = response_data["choices"][0]["message"]

            if choice.get("tool_calls"):
                # Assuming one tool call for simplicity in PoC
                tool_call_data = choice["tool_calls"][0]["function"]
                return ToolCall(
                    tool_name=tool_call_data["name"],
                    arguments=json.loads(tool_call_data["arguments"])
                )
            else:
                return choice["content"]

class OllamaProvider(LLMProvider):
    def __init__(self, model: str = "llama3", host: str = "http://127.0.0.1:11434"):
        self.model = model
        self.api_url = f"{host}/api/generate"

    async def generate(self, prompt: str, tools: Optional[List[Tool]] = None) -> Union[str, ToolCall]:
        full_prompt = prompt
        if tools:
            # Simulate tool calling for Ollama by injecting tool definitions into the prompt
            # and instructing the LLM to respond with a specific JSON format.
            tool_definitions = "\n".join([
                f"Tool Name: {tool.name}\nDescription: {tool.description}\nParameters: {json.dumps(tool.parameters.model_dump(mode='json'))}"
                for tool in tools
            ])
            full_prompt = f"""
You are an AI assistant. You have access to the following tools:
{tool_definitions}

If you need to use a tool, respond ONLY with a JSON object in the following format:
{{
    "tool_call": {{
        "tool_name": "the_tool_name",
        "arguments": {{"arg1": "value1", "arg2": "value2"}}
    }}
}}
Do NOT include any other text or explanation if you are calling a tool.

If you do not need to use a tool, respond with your answer as plain text.

User: {prompt}
"""
        json_data = {"model": self.model, "prompt": full_prompt, "stream": False}
        async with httpx.AsyncClient() as client:
            resp = await client.post(self.api_url, json=json_data, timeout=120)
            resp.raise_for_status()
            response_content = resp.json()["response"]

            # Attempt to parse as a tool call
            if tools: # Only attempt if tools were provided
                try:
                    parsed_response = json.loads(response_content)
                    if "tool_call" in parsed_response and \
                       isinstance(parsed_response["tool_call"], dict) and \
                       "tool_name" in parsed_response["tool_call"] and \
                       "arguments" in parsed_response["tool_call"]:
                        tool_call_data = parsed_response["tool_call"]
                        return ToolCall(
                            tool_name=tool_call_data["tool_name"],
                            arguments=tool_call_data["arguments"]
                        )
                except json.JSONDecodeError:
                    pass # Not a JSON tool call, proceed as normal text response

            return response_content
